create table public.customer_profiles (
  id uuid primary key default gen_random_uuid(),
  auth_user_id uuid unique references auth.users(id) on delete set null,
  full_name text not null check (char_length(trim(full_name)) between 2 and 100),
  phone text not null unique check (char_length(trim(phone)) between 6 and 32),
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.payment_receipts (
  id uuid primary key default gen_random_uuid(),
  customer_profile_id uuid references public.customer_profiles(id) on delete set null,
  customer_name text not null check (char_length(trim(customer_name)) between 2 and 100),
  phone text not null check (char_length(trim(phone)) between 6 and 32),
  payment_method text not null check (payment_method in ('vodafone_cash', 'binance_pay')),
  binance_phone text,
  storage_path text not null,
  original_filename text not null check (char_length(original_filename) between 1 and 255),
  mime_type text not null check (mime_type in ('image/jpeg', 'image/png', 'image/webp')),
  size_bytes integer not null check (size_bytes > 0 and size_bytes <= 5242880),
  whatsapp_shared_at timestamptz,
  status text not null default 'pending' check (status in ('pending', 'reviewed', 'rejected')),
  created_at timestamptz not null default now()
);

create table public.support_tickets (
  id uuid primary key default gen_random_uuid(),
  customer_profile_id uuid references public.customer_profiles(id) on delete set null,
  full_name text not null check (char_length(trim(full_name)) between 2 and 100),
  phone text not null check (char_length(trim(phone)) between 6 and 32),
  email text,
  subject text not null check (char_length(trim(subject)) between 3 and 180),
  message text not null check (char_length(trim(message)) between 10 and 5000),
  status text not null default 'open' check (status in ('open', 'in_progress', 'closed')),
  created_at timestamptz not null default now()
);

create index payment_receipts_created_at_idx on public.payment_receipts (created_at desc);
create index payment_receipts_phone_idx on public.payment_receipts (phone);
create index support_tickets_created_at_idx on public.support_tickets (created_at desc);

alter table public.customer_profiles enable row level security;
alter table public.payment_receipts enable row level security;
alter table public.support_tickets enable row level security;

revoke all on public.customer_profiles from anon, authenticated;
revoke all on public.payment_receipts from anon, authenticated;
revoke all on public.support_tickets from anon, authenticated;

